
public class Shembulli_01 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int sum = 0;
		for (int i = 0; i <= 10; i++) {
			sum += i;
			
		}
		System.out.println("Sum from 0 to 10 is " + sum);
		
		sum = 0;
		for (int i = 10; i <= 20; i++) {
			sum += i;
		}
		System.out.println("Sum from 10 to 20 is " + sum);
		
		sum = 0;
		for (int i = 20; i <= 30; i++) {
			sum += i;
		}
		System.out.println("Sum from 20 to 30 is " + sum);

	}

}
